// 中学受験 国語（漢字・語彙）単元の動く図解スライド（図のなかった単元に1つずつ）。
// 「❓なぜ？→答え」の連鎖で7枚以上。1枚ごとにまっさらな画面に描き、下にひとこと。
import type { DiagramElement, DiagramFigure } from './figures';
import type { Slide } from './diagram-kit';
import { show, bx, lb, ar, ln, ci, fresh, C, FILL } from './diagram-kit';

const cap = (t: string, color: string = C.ink, size = 12) => lb(160, 224, t, size, color, 'middle', true);
const hd = (t: string, color: string = C.ink, size = 13) => lb(160, 14, t, size, color, 'middle', true);
/** 1枚分のスライド。図（els）をまっさらな画面に描き、下にひとこと。 */
const sl = (note: string, caption: string, ...els: DiagramElement[]): Slide => ({ note, add: fresh(...els, cap(caption)) });
const slc = (note: string, caption: string, color: string, ...els: DiagramElement[]): Slide => ({ note, add: fresh(...els, cap(caption, color)) });

type RowOpt = { y0?: number; h?: number; gap?: number; lw?: number; c1?: string; f1?: string; c2?: string; f2?: string; s1?: number; s2?: number };
/** 左（語）→右（意味）の行を縦に並べる。 */
const rows = (items: [string, string][], opt?: RowOpt): DiagramElement[] => {
  const o = { y0: 28, h: 30, gap: 6, lw: 96, c1: C.blue, f1: FILL.blue, c2: C.green, f2: FILL.green, s1: 13, s2: 11, ...opt };
  const rx = 10 + o.lw + 24;
  return items.flatMap(([a, b], i) => {
    const y = o.y0 + i * (o.h + o.gap);
    return [bx(10, y, o.lw, o.h, a, o.c1, o.f1, o.s1), ar(10 + o.lw + 1, y + o.h / 2, rx - 1, y + o.h / 2, C.gray), bx(rx, y, 310 - rx, o.h, b, o.c2, o.f2, o.s2)];
  });
};
const rowsR = (items: [string, string][], opt?: RowOpt) => rows(items, { c1: C.red, f1: FILL.red, c2: C.red, f2: FILL.red, ...opt });
const rowsM = (items: [string, string][], opt?: RowOpt) => rows(items, { c1: C.main, f1: FILL.warm, c2: C.main, f2: FILL.warm, ...opt });
/** 横に等分した箱。 */
const cols = (labels: string[], y: number, h: number, c: string, f: string, size = 12, x0 = 10, x1 = 310, gap = 8): DiagramElement[] => {
  const n = labels.length;
  const w = (x1 - x0 - gap * (n - 1)) / n;
  return labels.map((t, i) => bx(x0 + i * (w + gap), y, w, h, t, c, f, size));
};
/** 全幅の箱。 */
const big = (t: string, y: number, c: string, f: string, h = 30, size = 13, x = 10, w = 300) => bx(x, y, w, h, t, c, f, size);
/** 左の主役（まる）から、右の目的語の箱へ矢印を引く図。 */
const aim = (actor: string, items: string[], c: string, f: string): DiagramElement[] => [
  ci(48, 104, 30, actor, c, f, 13),
  ...items.flatMap((t, i) => {
    const y = 32 + i * 50;
    return [ar(80, 104, 168, y + 17, c), bx(170, y, 130, 34, t, c, f, 13)];
  }),
];
/** 横一列の流れ（箱＋矢印）。 */
const fl = (labels: string[], y: number, h: number, c: string, f: string, size = 12): DiagramElement[] => {
  const n = labels.length;
  const gap = 18;
  const w = (300 - gap * (n - 1)) / n;
  return labels.flatMap((t, i) => {
    const x = 10 + i * (w + gap);
    const els: DiagramElement[] = [];
    if (i > 0) els.push(ar(x - gap + 1, y + h / 2, x - 1, y + h / 2, C.gray));
    els.push(bx(x, y, w, h, t, c, f, size));
    return els;
  });
};

